$ErrorActionPreference = "Stop"
$dashboardPort = 18765
$dashboardUrl = "http://127.0.0.1:$dashboardPort/"
$listener = Get-NetTCPConnection -State Listen -LocalPort $dashboardPort -ErrorAction SilentlyContinue

if (-not $listener) {
    $sshArguments = @(
        "-N",
        "-L", "127.0.0.1:${dashboardPort}:127.0.0.1:8765",
        "-i", "D:\openvela-vm\openvela_vm_ed25519",
        "-p", "2222",
        "-o", "BatchMode=yes",
        "-o", "ExitOnForwardFailure=yes",
        "-o", "ServerAliveInterval=30",
        "vela@127.0.0.1"
    )
    Start-Process -FilePath "ssh.exe" -ArgumentList $sshArguments -WindowStyle Hidden
}

for ($attempt = 0; $attempt -lt 10; $attempt++) {
    try {
        $health = Invoke-RestMethod -Uri "http://127.0.0.1:${dashboardPort}/api/v1/health" -TimeoutSec 2
        if ($health.ok) {
            Start-Process $dashboardUrl
            exit 0
        }
    } catch {
        Start-Sleep -Seconds 1
    }
}

throw "Formation dashboard did not become ready. Check the QEMU VM and formation-lab.service."

